BEGIN TRANSACTION;
CREATE TABLE config (collection TEXT, name TEXT, data BLOB);
CREATE TABLE file_managed (fid INTEGER, uuid TEXT, langcode TEXT, uid INTEGER,
  filename TEXT, uri TEXT, filemime TEXT, filesize INTEGER, status INTEGER,
  created INTEGER, changed INTEGER);
CREATE TABLE media (mid INTEGER, vid INTEGER, bundle TEXT, uuid TEXT, langcode TEXT);
CREATE TABLE media__field_media_image (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_media_image_target_id, field_media_image_alt, field_media_image_title, field_media_image_width, field_media_image_height);
CREATE TABLE media__field_media_oembed_video (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_media_oembed_video_value);
CREATE TABLE media_field_data (mid INTEGER, vid INTEGER, bundle TEXT, langcode TEXT,
  status INTEGER, uid INTEGER, name TEXT, thumbnail__target_id INTEGER,
  thumbnail__alt TEXT, thumbnail__title TEXT, thumbnail__width INTEGER,
  thumbnail__height INTEGER, created INTEGER, changed INTEGER,
  default_langcode INTEGER, revision_translation_affected INTEGER);
CREATE TABLE node (nid INTEGER, vid INTEGER, type TEXT, uuid TEXT, langcode TEXT);
CREATE TABLE node__body (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, body_value, body_summary, body_format);
CREATE TABLE node__field_attachment (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_attachment_target_id, field_attachment_display, field_attachment_description);
CREATE TABLE node__field_featured (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_featured_value);
CREATE TABLE node__field_image (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_image_target_id, field_image_alt, field_image_title, field_image_width, field_image_height);
CREATE TABLE node__field_link (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_link_uri, field_link_title, field_link_options);
CREATE TABLE node__field_media (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_media_target_id);
CREATE TABLE node__field_rating (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_rating_value);
CREATE TABLE node__field_sections (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_sections_target_id, field_sections_target_revision_id);
CREATE TABLE node__field_subtitle (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_subtitle_value);
CREATE TABLE node__field_tags (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_tags_target_id);
CREATE TABLE node_field_data (nid INTEGER, vid INTEGER, type TEXT, langcode TEXT,
  status INTEGER, uid INTEGER, title TEXT, created INTEGER, changed INTEGER,
  promote INTEGER, sticky INTEGER, default_langcode INTEGER,
  revision_translation_affected INTEGER);
CREATE TABLE paragraph__field_card_image (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_card_image_target_id, field_card_image_alt, field_card_image_title, field_card_image_width, field_card_image_height);
CREATE TABLE paragraph__field_cards (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_cards_target_id, field_cards_target_revision_id);
CREATE TABLE paragraph__field_heading (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_heading_value);
CREATE TABLE paragraph__field_text (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, field_text_value, field_text_format);
CREATE TABLE paragraphs_item (id INTEGER, revision_id INTEGER, type TEXT, uuid TEXT, langcode TEXT);
CREATE TABLE paragraphs_item_field_data (id INTEGER, revision_id INTEGER, type TEXT,
  langcode TEXT, status INTEGER, created INTEGER, parent_id TEXT, parent_type TEXT,
  parent_field_name TEXT, behavior_settings BLOB, default_langcode INTEGER,
  revision_translation_affected INTEGER);
CREATE TABLE path_alias (id INTEGER, revision_id INTEGER, uuid TEXT, langcode TEXT,
  path TEXT, alias TEXT, status INTEGER);
CREATE TABLE taxonomy_term__parent (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, parent_target_id INTEGER);
CREATE TABLE taxonomy_term_data (tid INTEGER, revision_id INTEGER, vid TEXT, uuid TEXT, langcode TEXT);
CREATE TABLE taxonomy_term_field_data (tid INTEGER, revision_id INTEGER, vid TEXT,
  langcode TEXT, status INTEGER, name TEXT, description__value TEXT,
  description__format TEXT, weight INTEGER, changed INTEGER,
  default_langcode INTEGER, revision_translation_affected INTEGER);
CREATE TABLE user__roles (bundle TEXT, deleted INTEGER, entity_id INTEGER, langcode TEXT, delta INTEGER, roles_target_id TEXT);
CREATE TABLE user__user_picture (bundle TEXT, deleted INTEGER, entity_id INTEGER, revision_id INTEGER, langcode TEXT, delta INTEGER, user_picture_target_id, user_picture_alt, user_picture_title, user_picture_width, user_picture_height);
CREATE TABLE users (uid INTEGER, uuid TEXT, langcode TEXT);
CREATE TABLE users_field_data (uid INTEGER, langcode TEXT, preferred_langcode TEXT,
  preferred_admin_langcode TEXT, name TEXT, pass TEXT, mail TEXT, timezone TEXT,
  status INTEGER, created INTEGER, changed INTEGER, access INTEGER, login INTEGER,
  init TEXT, default_langcode INTEGER);
COMMIT;
